import React from 'react';
import * as MdIcons from 'react-icons/md';
import { MdDesignServices } from 'react-icons/md';

/**
 * BentoTag Component
 * Reusable pill-shaped tag badge with Material Design icon and text for Bento Grid cards.
 *
 * @param {string|React.Component|React.ReactElement} icon - Material icon name (e.g. "MdDesignServices", "MdBrush") or component.
 * @param {string} text - Tag label (e.g. "Service Design").
 * @param {string} label - Alternative prop for text.
 * @param {string} className - Additional CSS class names.
 * @param {object} style - Additional inline styles.
 * @param {number} iconSize - Size of the Material icon (default 24).
 */
const BentoTag = ({
  icon = 'MdDesignServices',
  text,
  label,
  children,
  className = '',
  style = {},
  iconSize = 24,
}) => {
  const tagText = text || label || children || '';

  let IconComponent = MdDesignServices;

  if (typeof icon === 'string') {
    const formattedName = icon.startsWith('Md') ? icon : `Md${icon}`;
    if (MdIcons[formattedName]) {
      IconComponent = MdIcons[formattedName];
    }
  } else if (typeof icon === 'function') {
    IconComponent = icon;
  } else if (React.isValidElement(icon)) {
    return (
      <div className={`bento-tag ${className}`.trim()} style={style}>
        <span className="bento-tag-icon">{icon}</span>
        <span className="bento-tag-text">{tagText}</span>
      </div>
    );
  }

  return (
    <div className={`bento-tag ${className}`.trim()} style={style}>
      <span className="bento-tag-icon">
        <IconComponent size={iconSize} />
      </span>
      <span className="bento-tag-text">{tagText}</span>
    </div>
  );
};

export default BentoTag;
