import React from 'react';
import { Link } from 'gatsby';
import { useLanguage } from '../context/LanguageContext';
import aviationSvg from '../static/aviation.svg';
import aogSvg from '../static/aog.svg';
import dashboardGuidelinesSvg from '../static/dashboard-guidelines.svg';
import BentoTag from './BentoTag';
import profileAvatar from '../static/me.png';

const BentoGrid = ({ heroData, aboutData, worksData }) => {
  const { t, language } = useLanguage();

  const phrases = [
    'design thinking',
    'ux / ui design',
    'service design',
    'product design',
    'design'
  ];

  const [currentPhraseIndex, setCurrentPhraseIndex] = React.useState(0);
  const [typedText, setTypedText] = React.useState('');
  const [isDeleting, setIsDeleting] = React.useState(false);

  React.useEffect(() => {
    const fullText = phrases[currentPhraseIndex].toUpperCase();
    let timer;

    if (isDeleting) {
      timer = setTimeout(() => {
        setTypedText(prev => prev.slice(0, -1));
      }, 40); // speed of deletion
    } else {
      timer = setTimeout(() => {
        setTypedText(fullText.slice(0, typedText.length + 1));
      }, 80); // speed of typing
    }

    if (!isDeleting && typedText === fullText) {
      timer = setTimeout(() => {
        setIsDeleting(true);
      }, 1500); // pause when fully typed
    }

    if (isDeleting && typedText === '') {
      setIsDeleting(false);
      setCurrentPhraseIndex((prev) => (prev + 1) % phrases.length);
    }

    return () => clearTimeout(timer);
  }, [typedText, isDeleting, currentPhraseIndex]);

  const rawTitle = heroData?.frontmatter?.title || (language === 'pt'
    ? 'MOLDANDO PRODUTOS,<br />EXPERIÊNCIAS E O MUNDO<br />ATRAVÉS DO<br /><span class="action">DESIGN</span>'
    : 'SHAPING PRODUCTS,<br />EXPERIENCES AND THE WORLD<br />THROUGH<br /><span class="action">DESIGN</span>');

  const parts = rawTitle.split(/<span class="action">/i);
  const prefix = parts[0] || '';

  const images = {
    aviation: aviationSvg,
    aog: aogSvg,
    dashboardGuidelines: dashboardGuidelinesSvg,
    profileAvatar: profileAvatar
  };

  return (
    <div>
      {/* HERO BENTO GRID SECTION */}
      <section className="container bento-hero-section" id="home">
        <div className="bento-grid">

          {/* Row 1: Title Card & Wooden Table Book */}
          <div className="bento-item title-card">
            <svg className="bento-bg-blob" viewBox="0 0 728 774" fill="none" xmlns="http://www.w3.org/2000/svg">
              <path d="M209.23 492.909C167.957 582.974 201.473 761.298 378.374 710.8C617.512 642.536 663.284 467.69 596.38 287.408C522.606 88.6144 312.404 41.0368 163.83 149.715C15.2554 258.393 250.502 402.845 209.23 492.909Z" fill="#D1D5DB" fillOpacity="0.5" />
              <path d="M556.492 510.166C674.291 361.65 613.273 178.947 461.36 115.724C423.433 99.9392 394.978 103.524 372.222 117.853C349.422 132.21 332.269 157.394 317.073 184.967C309.478 198.749 302.384 213.103 295.317 226.981C288.254 240.852 281.218 254.246 273.75 266.078C258.832 289.718 242.107 307.266 219.827 309.844C175.896 314.927 123.746 344.512 97.6594 386.764C84.6247 407.876 78.1061 432.135 82.3472 458.08C86.5889 484.028 101.603 511.721 131.742 539.678C213.311 615.34 292.783 641.6 365.179 632.165C437.59 622.728 503.032 577.567 556.492 510.166Z" stroke="black" />
            </svg>
            <h1 className="hero-title">
              <span dangerouslySetInnerHTML={{ __html: prefix }} />
              <span className="action">{typedText}</span>
            </h1>
          </div>

          <Link to="/project/aircraft-on-ground" className="bento-item img-card tall-card">
            <div className="bento-item tag-card">
              <BentoTag icon="MdDesignServices" text={t('bento_service_design_tag')} />
            </div>
            <div className="description-card">
              <p>{t('bento_service_design_title')}</p>
            </div>
            <div className='content-card'>
              <svg width="118" height="118" viewBox="0 0 118 118" fill="none" xmlns="http://www.w3.org/2000/svg">
                <g clip-path="url(#clip0_689_377)">
                  <path d="M110.92 80.1415L73.2091 17.6015C71.6842 15.2161 69.5833 13.2529 67.1 11.893C64.6168 10.5331 61.8311 9.82031 58.9999 9.82031C56.1687 9.82031 53.383 10.5331 50.8998 11.893C48.4165 13.2529 46.3156 15.2161 44.7908 17.6015L7.07992 80.1415C5.74777 82.3622 5.02372 84.8944 4.98056 87.4836C4.93741 90.0728 5.57668 92.6277 6.83409 94.8915C8.28785 97.4397 10.3921 99.5562 12.9317 101.025C15.4714 102.493 18.3554 103.261 21.2891 103.25H96.7108C99.6251 103.281 102.496 102.543 105.034 101.11C107.572 99.6768 109.687 97.5998 111.166 95.0882C112.46 92.8009 113.12 90.2092 113.077 87.5814C113.033 84.9536 112.289 82.3851 110.92 80.1415ZM102.562 90.2207C101.971 91.2365 101.113 92.0712 100.082 92.6345C99.0505 93.1978 97.8848 93.4683 96.7108 93.4165H21.2891C20.1151 93.4683 18.9493 93.1978 17.918 92.6345C16.8867 92.0712 16.0292 91.2365 15.4383 90.2207C15.0067 89.4733 14.7795 88.6254 14.7795 87.7624C14.7795 86.8993 15.0067 86.0515 15.4383 85.304L53.1983 22.7149C53.8768 21.8186 54.7537 21.0917 55.7603 20.5912C56.7669 20.0908 57.8758 19.8303 58.9999 19.8303C60.1241 19.8303 61.2329 20.0908 62.2395 20.5912C63.2461 21.0917 64.1231 21.8186 64.8016 22.7149L102.512 85.2549C102.961 86.0037 103.201 86.8584 103.21 87.7311C103.219 88.6038 102.995 89.4631 102.562 90.2207Z" fill="white" />
                  <path d="M59.0002 83.5833C61.7156 83.5833 63.9168 81.3821 63.9168 78.6667C63.9168 75.9513 61.7156 73.75 59.0002 73.75C56.2848 73.75 54.0835 75.9513 54.0835 78.6667C54.0835 81.3821 56.2848 83.5833 59.0002 83.5833Z" fill="white" />
                  <path d="M59.0002 39.3335C57.6962 39.3335 56.4456 39.8515 55.5236 40.7736C54.6015 41.6956 54.0835 42.9462 54.0835 44.2502V63.9168C54.0835 65.2208 54.6015 66.4714 55.5236 67.3934C56.4456 68.3155 57.6962 68.8335 59.0002 68.8335C60.3041 68.8335 61.5547 68.3155 62.4768 67.3934C63.3988 66.4714 63.9168 65.2208 63.9168 63.9168V44.2502C63.9168 42.9462 63.3988 41.6956 62.4768 40.7736C61.5547 39.8515 60.3041 39.3335 59.0002 39.3335Z" fill="white" />
                </g>
                <defs>
                  <clipPath id="clip0_689_377">
                    <rect width="118" height="118" fill="white" />
                  </clipPath>
                </defs>
              </svg>
              <h3 >Aircraft on Ground</h3>
            </div>

            <img src={images.aviation} alt="Aviation" className="bento-image" />
          </Link>

          {/* Row 2: Dashboard Guidelines & Aerial Forest */}
          <Link to="/project/guideline-dashboards" className="bento-item img-card wide-card dashboard-card">
            <div className="bento-item tag-card">
              <BentoTag icon="MdSpaceDashboard" text={t('bento_dashboard_tag')} iconSize={18} />
            </div>
            <div className="description-card">
              <p>{t('bento_dashboard_title')}</p>
            </div>
            <img src={images.dashboardGuidelines} alt={t('bento_dashboard_title')} className="bento-image" />
          </Link>

          <div className="bento-item wide-card coming-soon-card">
            <span className="coming-soon-label">{t('coming_soon')}</span>
          </div>

          {/* Row 3: Reserved Project Slots (Cards 4 to 7) */}
          <div className="bento-item square-card coming-soon-card">
            <span className="coming-soon-label">{t('coming_soon')}</span>
          </div>

          <div className="bento-item square-card coming-soon-card">
            <span className="coming-soon-label">{t('coming_soon')}</span>
          </div>

          <div className="bento-item square-card coming-soon-card">
            <span className="coming-soon-label">{t('coming_soon')}</span>
          </div>

          <div className="bento-item square-card coming-soon-card">
            <span className="coming-soon-label">{t('coming_soon')}</span>
          </div>

        </div>
      </section>

      {/* ABOUT ME SECTION */}
      <section className="about-section" id="about">
        <div className="container">
          <div className="about-card">
            <div className="about-left">
              <h2 className="section-title" style={{ marginBottom: '10px' }}>
                {aboutData?.frontmatter?.title || t('nav_about')}
              </h2>
              <div
                className="about-text"
                dangerouslySetInnerHTML={{ __html: aboutData?.html || '' }}
              />
            </div>
            <div className="about-avatar-container">
              <img
                src={images.profileAvatar}
                alt="Matheus Kerschner profile"
                className="about-avatar"
              />
            </div>
          </div>
        </div>
      </section>


    </div>
  );
};

export default BentoGrid;
